INSERT INTO work_queue (id,task_type,payload,status,created_at) SELECT 'pending-backfill-guard','metadata','{}','guard_failed',unixepoch() WHERE changes()!=2 OR (SELECT COUNT(*) FROM song_masters WHERE album_id='al-cfe9a2e735c7900a5b0e96f5ddf53069')!=13 OR (SELECT song_count FROM albums WHERE id='al-cfe9a2e735c7900a5b0e96f5ddf53069')!=13 OR (SELECT size FROM albums WHERE id='al-cfe9a2e735c7900a5b0e96f5ddf53069')!=(SELECT COALESCE(SUM(si.size),0) FROM song_instances si JOIN song_masters sm ON sm.id=si.master_id WHERE sm.album_id='al-cfe9a2e735c7900a5b0e96f5ddf53069');
